"""63편 광안리 불꽃축제 그림 프롬프트 → 63_prompts.txt (python 63_prompts.py). 스타일은 2TAN-MASTER §5(11/6판, 고리·동그라미 금지)."""
S = next(l.strip() for l in open("2TAN-MASTER.md", encoding="utf-8") if l.startswith("Style: a hyper-detailed"))
E = "Keep exactly the same place, objects, red props and light."
HI = "A high oblique aerial view from about 150 m up, looking 35 degrees down"
BR = ("Gwangan Bridge in Busan: a long double-deck suspension bridge with a steel truss deck (an upper road deck and a lower road deck), "
      "two tall white towers with rounded arch tops and long main cables, crossing the bay in front of the wide crescent sandy beach of Gwangalli "
      "with a dense row of hotels and apartment towers behind the beach")
DUSK = "Blue hour just after sunset: the sky is still bright deep blue with a soft orange glow on the horizon, city lights on, the scene bright and inviting, not a dark night."
FW = "golden fireworks bursting high above the bridge and a long glittering curtain of golden sparks pouring straight down from the edge of the upper deck into the sea like a waterfall"
P = [
 ("01", None, f"{HI} from over the sea toward {BR}; the bridge runs across the lower half of the frame and the beach behind it, the sky and horizon fill the top fifth. {FW}. {DUSK} No red props."),
 ("01b", None, f"Seen from the sandy beach of Gwangalli at the height of a person: the beach is packed with a big crowd of tiny white figurines all facing the sea; across the bay {BR}, with {FW}. {DUSK} No red props."),
 ("02", None, f"Seen from just above the sea surface close to the side of the bridge: a long glittering curtain of golden sparks pours straight down from the edge of the upper deck of the double-deck steel truss suspension bridge into the sea and reflects on the water. {DUSK} No red props."),
 ("03", None, "Seen from above at an angle on a clear sunny afternoon: the upper deck of a long double-deck steel truss suspension bridge over the sea; the outer lane is closed with orange traffic cones and barriers, a small work truck is parked in the closed lane, and tiny white figurine workers in plain white helmets fix long rows of small grey tubes and black cables along the outer railing of the deck; cars still drive in the other lanes. No red props."),
 ("04", "03", "Change only the camera: it is now close to the outer railing of the upper deck, where a long row of small grey tubes on a metal rack and bundled black cables are clamped to the railing; one figurine worker checks a cable; the sea far below. One thin red 3D arrow points at the row of tubes, smaller than the rack."),
 ("05", None, "A large 3D map of the Busan coast in miniature seen from high above at an angle: the crescent sandy beach of Gwangalli with its row of hotels, the long double-deck suspension bridge across the bay in front of it, a rocky green headland with cliffs to the south and a small wooded island-like cape with a lighthouse to the north-east, the city and mountains behind; three small thin red 3D map pins stand on the beach, the rocky headland and the wooded cape. Bright daylight."),
 ("06", None, "Seen from above at an angle on calm sea on a sunny afternoon: a large flat grey steel barge anchored off a sandy city beach, its deck covered with neat rows of dark firework mortar tubes in wooden racks and black cables leading to a small grey control box; a small tugboat beside it; two tiny white figurine workers in plain white helmets on deck; the long double-deck suspension bridge in the distance. No red props."),
 ("07", "06", "Change only the time and action: it is now blue hour just after sunset with the sky still bright deep blue, and bright golden fireworks are shooting up in streaks from the mortar tubes on the barge and bursting high above; the barge deck glows; no figurines on the barge."),
 ("08", None, "On the deck of a grey steel barge on a sunny afternoon: one very large round firework shell, a smooth brown paper-wrapped sphere about as tall as a figurine's waist, sits on a wooden cradle next to a wide steel mortar tube; one tiny white figurine worker in a plain white helmet stands beside it for scale; a thin bright red 3D horizontal dimension line with end ticks spans the width of the shell, thinner than the shell. Calm sea and a long bridge in the distance."),
 ("09", None, f"{HI} over the sea: one gigantic golden chrysanthemum firework bursting high above {BR}, its sparks spreading wider than the bridge towers are tall, reflected in the sea. {DUSK} No red props."),
 ("10", None, "Seen from above at a 45-degree angle at blue hour with the sky still bright: the wide sandy beach of Gwangalli packed with a huge crowd of tiny white figurines, divided into large blocks by low white safety fences with open aisles between them; tiny figurines in bright orange vests stand at the aisle openings; a beachfront road with hotels behind. The long suspension bridge across the bay at the top. No red props."),
 ("11", None, "Inside a clean, brightly lit control room in miniature seen from above at a 45-degree angle: a wall of many monitors showing only blurred aerial views of a crowded beach (no letters, numbers or icons on any screen), a long desk with plain keyboards, three tiny white figurine operators seated and one standing pointing at the wall. No red props. No window."),
 ("12", None, "A split view in miniature, divided down the middle by one thin vertical bright red 3D line. Left half: the wide Han River in Seoul at blue hour with a riverside park packed with tiny white figurines and golden fireworks bursting over the river in front of a skyline of glass towers. Right half: the crescent beach of Gwangalli in Busan at blue hour with the long double-deck suspension bridge and golden fireworks pouring from its deck like a waterfall. The same bright blue-hour light on both sides. No other red props."),
 ("13", None, "Seen from above at an angle in the afternoon: the upper road deck of a long double-deck steel truss suspension bridge over the sea is completely empty of cars, closed at the entrance ramp by a row of orange barriers and traffic cones; on the lower deck and the city roads beside the bridge, cars queue; tiny white figurine traffic staff in orange vests at the barriers. No red props."),
 ("14", None, f"Seen from very high above the sea at an angle: the whole Busan coast at blue hour, the sky filling the top fifth; in the middle {BR} with {FW}; two flat barges on the sea firing golden fireworks; the crowded beach behind; a rocky headland and a wooded cape at the edges. {DUSK} No red props."),
]
with open("63_prompts.txt", "w", encoding="utf-8") as f:
    for n, src, t in P:
        if src: f.write(f"[{n}.jpg] ({src}.jpg를 열어 편집)\n{E} {t} No letters or numbers anywhere.\n\n")
        else: f.write(f"[{n}.jpg]\n{t} {S}\n\n")
print(len(P))
